USE NHL_PredictDB;

-- INSERTS PARTIDOS NHL CON NHL_GAMEID


SELECT COUNT(*) AS Total_Partidos
FROM Partidos;

SELECT PartidoID,
       NHL_GameID,
       Fecha_Partido,
       Equipo_Local,
       Equipo_Visitante
FROM Partidos
LIMIT 5;

SELECT NHL_GameID
FROM Partidos
WHERE NHL_GameID IS NOT NULL;

SELECT COUNT(*) AS Total_GameIDs
FROM Partidos
WHERE NHL_GameID IS NOT NULL;

SELECT NHL_GameID
FROM Partidos
WHERE NHL_GameID IS NOT NULL;

SELECT NHL_GameID
FROM Partidos
WHERE NHL_GameID IS NOT NULL
LIMIT 10000;